package com.meterflow.subscriptions;
import org.springframework.data.domain.Page; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Sort; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.security.access.AccessDeniedException; import java.time.*; import java.util.*; import java.math.*;
@RestController @RequestMapping("/api/subscriptions") public class SubscriptionController {
 private final SubscriptionRepository repo; private final com.meterflow.catalogue.PlanRepository plans; private final PlanChangeRepository changes; private final com.meterflow.catalogue.PricingService pricing; public SubscriptionController(SubscriptionRepository r,com.meterflow.catalogue.PlanRepository p,PlanChangeRepository c,com.meterflow.catalogue.PricingService pr){repo=r;plans=p;changes=c;pricing=pr;}
 public record Input(@NotBlank String customerId,@NotNull UUID planId,@NotNull LocalDate periodStart,@NotNull LocalDate periodEnd,Integer seatCount,LocalDate trialEnd){}
 public record ScheduleInput(@NotNull UUID planId,@NotNull LocalDate effectiveDate){}
 public record ChangeInput(@NotNull UUID planId){}
 @GetMapping public List<Subscription> all(Authentication auth){return isAdmin(auth)?repo.findAll():repo.findByCustomerIdOrderByPeriodStartDesc(auth.getName());}
 @PreAuthorize("hasRole('ADMIN')") @GetMapping("/page") public Page<Subscription> page(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,Authentication auth){if(page<0||size<1||size>100)throw new IllegalArgumentException("page must be >= 0 and size must be 1..100");var pageable=PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"periodStart"));return isAdmin(auth)?repo.findAll(pageable):repo.findByCustomerIdOrderByPeriodStartDesc(auth.getName(),pageable);}
 @PostMapping public Subscription create(@Valid @RequestBody Input i){if(!i.periodEnd().isAfter(i.periodStart()))throw new IllegalArgumentException("Period end must be after start");plans.findById(i.planId()).orElseThrow(()->new IllegalArgumentException("Plan not found"));var sub=new Subscription(i.customerId(),i.planId(),i.periodStart(),i.periodEnd());if(i.seatCount()!=null)sub.setSeatCount(i.seatCount());if(i.trialEnd()!=null)sub.startTrial(i.trialEnd());return repo.save(sub);}
 @PreAuthorize("hasRole('ADMIN')") @PostMapping("/{id}/schedule-plan-change") public Subscription schedule(@PathVariable UUID id,@Valid @RequestBody ScheduleInput input){var sub=repo.findById(id).orElseThrow();plans.findById(input.planId()).orElseThrow(()->new IllegalArgumentException("Plan not found"));sub.schedulePlanChange(input.planId(),input.effectiveDate());return repo.save(sub);}
 @PreAuthorize("hasRole('ADMIN')") @PostMapping("/{id}/seats") public Subscription seats(@PathVariable UUID id,@RequestParam @Min(1) int count){var sub=repo.findById(id).orElseThrow();sub.setSeatCount(count);return repo.save(sub);}
 @PreAuthorize("hasRole('ADMIN')") @PostMapping("/{id}/change-plan") public Map<String,Object> changePlan(@PathVariable UUID id,@Valid @RequestBody ChangeInput input){var sub=repo.findById(id).orElseThrow();var old=plans.findById(sub.getPlanId()).orElseThrow();var next=plans.findById(input.planId()).orElseThrow();if(!old.getCurrency().equals(next.getCurrency()))throw new IllegalArgumentException("Plan change currencies must match");LocalDate effective=LocalDate.now(ZoneOffset.UTC);if(effective.isBefore(sub.getPeriodStart()))effective=sub.getPeriodStart();if(!effective.isBefore(sub.getPeriodEnd()))throw new IllegalStateException("Subscription period ended");long total=java.time.temporal.ChronoUnit.DAYS.between(sub.getPeriodStart(),sub.getPeriodEnd());long remain=java.time.temporal.ChronoUnit.DAYS.between(effective,sub.getPeriodEnd());BigDecimal delta=pricing.calculate(next,BigDecimal.ZERO,BigDecimal.valueOf(sub.getSeatCount())).subtract(pricing.calculate(old,BigDecimal.ZERO,BigDecimal.valueOf(sub.getSeatCount()))).multiply(BigDecimal.valueOf(remain)).divide(BigDecimal.valueOf(total),2,java.math.RoundingMode.HALF_UP);sub.changePlan(next.getId());repo.save(sub);var audit=changes.save(new PlanChange(sub.getId(),old.getId(),next.getId(),delta,next.getCurrency(),effective));return Map.of("subscription",sub,"change",audit,"prorationDelta",delta,"currency",next.getCurrency());}
 @GetMapping("/{id}/plan-changes") public List<PlanChange> history(@PathVariable UUID id,Authentication auth){var sub=repo.findById(id).orElseThrow();guard(sub,auth);return changes.findBySubscriptionIdOrderByEffectiveDateDesc(id);}
 @PreAuthorize("hasRole('ADMIN')") @PostMapping("/{id}/pause") public Subscription pause(@PathVariable UUID id){var s=repo.findById(id).orElseThrow();s.pause();return repo.save(s);}
 @PreAuthorize("hasRole('ADMIN')") @PostMapping("/{id}/resume") public Subscription resume(@PathVariable UUID id){var s=repo.findById(id).orElseThrow();s.resume();return repo.save(s);}
 @PreAuthorize("hasRole('ADMIN')") @PostMapping("/{id}/cancel") public Subscription cancel(@PathVariable UUID id){var s=repo.findById(id).orElseThrow();s.cancel();return repo.save(s);}

 private boolean isAdmin(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));}
 private void guard(Subscription s,Authentication a){if(!isAdmin(a)&&!a.getName().equals(s.getCustomerId()))throw new AccessDeniedException("Customers may only access their own subscription.");}
}
